<?php
namespace Tests\Feature;use App\Models\Order;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Str;use Tests\TestCase;
class Pack006PaymentTest extends TestCase{use RefreshDatabase;private function order():Order{return Order::create(['uuid'=>(string)Str::uuid(),'number'=>'AMER-PAY-1','status'=>'pending_payment','payment_status'=>'unpaid','currency'=>'BDT','subtotal'=>1000,'grand_total'=>1000,'customer_name'=>'Buyer','phone'=>'01700000000','country_code'=>'BD','city'=>'Dhaka','address'=>'Address']);}public function test_cod_confirms_order_without_marking_paid():void{$this->seed();$o=$this->order();$this->withSession(['last_order_uuid'=>$o->uuid])->post(route('payment.initiate',$o->uuid),['method'=>'cod'])->assertRedirect();$this->assertDatabaseHas('orders',['id'=>$o->id,'status'=>'confirmed','payment_status'=>'cod_pending']);$this->assertDatabaseHas('payment_transactions',['order_id'=>$o->id,'gateway'=>'cod','status'=>'authorized']);}public function test_unconfigured_gateway_never_fakes_success():void{$this->seed();$o=$this->order();$this->withSession(['last_order_uuid'=>$o->uuid])->post(route('payment.initiate',$o->uuid),['method'=>'bkash'])->assertSessionHasErrors('payment');$this->assertDatabaseMissing('orders',['id'=>$o->id,'payment_status'=>'paid']);}}
